import { Box, keyframes } from "@mui/material";
import React from "react";

const float = keyframes`
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-20px);
  }
`;

const rotate = keyframes`
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
`;

const pulse = keyframes`
  0%, 100% {
    opacity: 0.4;
    transform: scale(1);
  }
  50% {
    opacity: 0.8;
    transform: scale(1.1);
  }
`;

const AnimatedBackground: React.FC = () => {
  return (
    <Box
      sx={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        zIndex: -1,
        overflow: "hidden",
        pointerEvents: "none",
      }}
    >
      {/* Floating Orbs */}
      {[...Array(6)].map((_, i) => (
        <Box
          key={i}
          sx={{
            position: "absolute",
            width: `${60 + i * 20}px`,
            height: `${60 + i * 20}px`,
            borderRadius: "50%",
            background: `linear-gradient(135deg, 
              ${i % 2 === 0 ? "rgba(102, 126, 234, 0.1)" : "rgba(240, 147, 251, 0.1)"}, 
              ${i % 2 === 0 ? "rgba(118, 75, 162, 0.1)" : "rgba(245, 87, 108, 0.1)"})`,
            backdropFilter: "blur(10px)",
            border: "1px solid rgba(255, 255, 255, 0.1)",
            left: `${10 + i * 15}%`,
            top: `${10 + i * 12}%`,
            animation: `${float} ${3 + i * 0.5}s ease-in-out infinite`,
            animationDelay: `${i * 0.2}s`,
          }}
        />
      ))}

      {/* Rotating Rings */}
      {[...Array(3)].map((_, i) => (
        <Box
          key={`ring-${i}`}
          sx={{
            position: "absolute",
            width: `${200 + i * 100}px`,
            height: `${200 + i * 100}px`,
            border: "2px solid",
            borderColor:
              i % 2 === 0
                ? "rgba(102, 126, 234, 0.1)"
                : "rgba(240, 147, 251, 0.1)",
            borderRadius: "50%",
            right: `${-50 + i * 20}px`,
            bottom: `${-50 + i * 30}px`,
            animation: `${rotate} ${20 + i * 10}s linear infinite`,
            "&::before": {
              content: '""',
              position: "absolute",
              top: "50%",
              left: "50%",
              width: "8px",
              height: "8px",
              background: i % 2 === 0 ? "#667eea" : "#f093fb",
              borderRadius: "50%",
              transform: "translate(-50%, -50%)",
              animation: `${pulse} 2s ease-in-out infinite`,
            },
          }}
        />
      ))}

      {/* Grid Pattern */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          backgroundImage: `
            linear-gradient(rgba(102, 126, 234, 0.03) 1px, transparent 1px),
            linear-gradient(90deg, rgba(102, 126, 234, 0.03) 1px, transparent 1px)
          `,
          backgroundSize: "50px 50px",
          animation: `${pulse} 4s ease-in-out infinite`,
        }}
      />

      {/* Gradient Overlay */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          background: `
            radial-gradient(circle at 20% 80%, rgba(102, 126, 234, 0.1) 0%, transparent 50%),
            radial-gradient(circle at 80% 20%, rgba(240, 147, 251, 0.1) 0%, transparent 50%),
            radial-gradient(circle at 40% 40%, rgba(79, 172, 254, 0.05) 0%, transparent 50%)
          `,
        }}
      />
    </Box>
  );
};

export default AnimatedBackground;
